import sys

def main():
    n = int(sys.stdin.readline().strip())

    students = []

    for _ in range(n):
        name_line = sys.stdin.readline().strip()
        id_val = int(sys.stdin.readline().strip())
        grades_line = sys.stdin.readline().strip()
        grades = list(map(float, grades_line.split()))

        students.append({
            'name': name_line,
            'id': id_val,
            'grades': grades,
            'average': sum(grades) / len(grades),
            'status': None
        })

    # Determine status
    for s in students:
        avg = s['average']
        if avg >= 50:
            # Use grade category
            if avg >= 85:
                s['status'] = ('category', 1, 'Excellent')
            elif avg >= 70:
                s['status'] = ('category', 2, 'Good')
            else:
                s['status'] = ('category', 3, 'Average')
        else:
            s['status'] = ('passfail', 'F')

    # Output
    for s in students:
        print(s['name'])
        print(s['id'])
        grades_str = ' '.join(f'{g:.1f}' for g in s['grades'])
        print(grades_str)
        print(f'{s["average"]:.1f}')
        if s['status'][0] == 'category':
            print(s['status'][1])
        else:
            print('F')

if __name__ == "__main__":
    main()
